import sqlite3, os
p='magaza.db'
print(os.path.exists(p), os.path.getsize(p))
con=sqlite3.connect(p)
cur=con.cursor()
for row in cur.execute("select name, sql from sqlite_master where type='table'"):
    print(row[0], row[1])
for t in ['musteriler','urunler','siparisler','siparis_kalemleri','iadeler']:
    print('---',t)
    try:
        print(cur.execute(f'select count(*) from {t}').fetchone()[0])
        for r in cur.execute(f'select * from {t} limit 3'):
            print(r)
    except Exception as e:
        print('ERR',e)
con.close()
